const crypto = require('node:crypto');
exports.seal = (secret, text) => { const c = crypto.createCipher('aes-256-cbc', secret); return c.update(text, 'utf8', 'hex') + c.final('hex'); };
exports.open = (secret, hex) => { const d = crypto.createDecipher('aes-256-cbc', secret); return d.update(hex, 'hex', 'utf8') + d.final('utf8'); };

const crypto = require('node:crypto');
const key = (secret, salt) => crypto.scryptSync(secret, salt, 32);
exports.seal = (secret, text) => { const salt = crypto.randomBytes(16), iv = crypto.randomBytes(16); const c = crypto.createCipheriv('aes-256-cbc', key(secret, salt), iv); return [salt, iv, Buffer.concat([c.update(text, 'utf8'), c.final()])].map((b) => b.toString('hex')).join(':'); };
exports.open = (secret, sealed) => { const [salt, iv, ct] = sealed.split(':').map((h) => Buffer.from(h, 'hex')); const d = crypto.createDecipheriv('aes-256-cbc', key(secret, salt), iv); return Buffer.concat([d.update(ct), d.final()]).toString('utf8'); };

